package com.bank.jvm;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.concurrent.TimeUnit;

// Correct JMH benchmark: concatenation vs StringBuilder for bank statements.
@BenchmarkMode(Mode.AverageTime)              // measure average time per operation
@OutputTimeUnit(TimeUnit.MICROSECONDS)        // report in microseconds
@Warmup(iterations = 5, time = 1)             // 5 warm-up iterations so JIT compiles the hot path
@Measurement(iterations = 5, time = 1)        // 5 measured iterations
@Fork(2)                                      // run in 2 separate JVMs for isolation
@State(Scope.Benchmark)                       // shared state across the benchmark
public class StatementBuildingBenchmark {

    @Param({"10", "100", "1000"})             // run each benchmark for these line counts
    private int lineCount;

    private String accountId;
    private long balance;

    @Setup(Level.Trial)                        // prepare state BEFORE measurement (not timed)
    public void setup() {
        accountId = "SAV2001";
        balance = 1_000_000L;
    }

    // WRONG-STYLE approach under test: string concatenation in a loop.
    @Benchmark
    public String concatenation() {
        String statement = "";
        for (int i = 0; i < lineCount; i++) {
            statement = statement + "Line " + i + " " + accountId + " bal=" + balance + "\n";
        }
        return statement;                      // RETURN consumes the value -> no dead-code elimination
    }

    // RIGHT-STYLE approach under test: StringBuilder.
    @Benchmark
    public void stringBuilder(Blackhole blackhole) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < lineCount; i++) {
            sb.append("Line ").append(i).append(' ')
              .append(accountId).append(" bal=").append(balance).append('\n');
        }
        blackhole.consume(sb.toString());      // Blackhole forces the result to be "used"
    }
}

