package com.bank.jvm;

import java.util.logging.*;

// Demonstrates WHY a nanoTime loop is NOT a valid benchmark.
public class NaiveBenchmarkDemo {
    private static final Logger log = Logger.getLogger(NaiveBenchmarkDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // FLAW 1: no warm-up -> this times interpreted / C1 code, not steady state.
        long start = System.nanoTime();
        long sum = 0;
        for (int i = 0; i < 10_000_000; i++) {
            sum += expensiveFeeCalc(i);  // FLAW 2: if 'sum' were unused, JIT deletes the whole loop
        }
        long elapsed = System.nanoTime() - start;
        // We print 'sum' ONLY so the JIT does not eliminate the loop in this demo.
        log.warning("Naive nanoTime 'benchmark' measured " + (elapsed / 1_000_000)
                + "ms (UNRELIABLE: no warm-up, no fork, GC noise, DCE risk). sum=" + sum);
        log.info("Use JMH instead: run StatementBuildingBenchmark for trustworthy numbers.");
    }

    private static long expensiveFeeCalc(int i) {
        return (long) (i * 0.0005);  // FLAW 3: constant-foldable -> JIT may precompute it away
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
